ALTER TABLE "pembayaran" ADD CONSTRAINT "pembayaran_jumlah_pembayaran_check" CHECK ((jumlah_pembayaran > (0)::numeric));
ALTER TABLE "pembayaran" ADD CONSTRAINT "pembayaran_status_pembayaran_check" CHECK (((status_pembayaran)::text = ANY ((ARRAY['menunggu'::character varying, 'berhasil'::character varying, 'gagal'::character varying, 'kedaluwarsa'::character varying])::text[])));
ALTER TABLE "reservasi" ADD CONSTRAINT "reservasi_check" CHECK ((jam_mulai < jam_selesai));
