ALTER TABLE "reservasi" ADD CONSTRAINT "reservasi_check2" CHECK (((((status_reservasi)::text = 'ditahan'::text) AND (hold_expires_at IS NOT NULL)) OR (((status_reservasi)::text <> 'ditahan'::text) AND (hold_expires_at IS NULL))));
